        # list_for_customer returns creation order, so reverse it for newest first.
        for order in reversed(orders):
            summary = self._service.summarize(order)
            history.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Non-cancelled order count and the sum of their totals, as the order history reports them."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, value = self._lifetime_value(customer_id)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": value})

